SELECT DISTINCT p.namespace,p.id,p.content_hash,p.content_json FROM plan_revisions p JOIN (SELECT b.* FROM chrome_attempt_bindings b WHERE b.namespace=:Namespace AND b.profile_channel=:ProfileChannel AND b.browser_instance=:BrowserInstance AND b.scope_hash=:ScopeHash AND b.id>:AfterID ORDER BY b.id LIMIT 128) selected ON p.namespace=selected.namespace AND p.id=selected.plan_id WHERE p.namespace=:Namespace
